(function () {
    'use strict';

    /* eslint-disable */

    function parseUrl(url) {
        const data = {};

        if (!url) {
            return data;
        }

        url = url.substring(url.indexOf('?') + 1);

        url.replace(/\+/g, ' ').split('&').forEach(function (value) {
            const param = value.split('=');
            const key = decodeURIComponent(param[0]);

            if (param.length === 2) {
                const val = decodeURIComponent(param[1]);

                if (typeof val === 'string' && val.length) {
                    data[key] = val;
                }
            }
        });

        return data;
    }

    function mimeFromExt(url) {
        const ext = url.split('.').pop().toLowerCase();

        const map = {
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg',
            'png': 'image/png',
            'gif': 'image/gif',
            'webp': 'image/webp',
            'apng': 'image/apng',
            'mp4': 'video/mp4',
            'm4v': 'video/x-m4v',
            'ogg': 'audio/ogg',
            'ogv': 'video/ogg',
            'webm': 'video/webm',
            'mp3': 'audio/mpeg',
            'wav': 'audio/wav',
            'pdf': 'application/pdf',
            'zip': 'application/zip',
            'tar': 'application/x-tar',
            'doc': 'application/msword',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'dot': 'application/msword',
            'dotx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.template',
            'xls': 'application/vnd.ms-excel',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'ppt': 'application/vnd.ms-powerpoint',
            'pps': 'application/vnd.ms-powerpoint',
            'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
            'ppsx': 'application/vnd.openxmlformats-officedocument.presentationml.slideshow',
            'odt': 'application/vnd.oasis.opendocument.text',
            'odp': 'application/vnd.oasis.opendocument.presentation',
            'ods': 'application/vnd.oasis.opendocument.spreadsheet',
            'odg': 'application/vnd.oasis.opendocument.graphics'
        };

        return map[ext] || '';
    }

    function isAdmin(value) {
        return value && value.indexOf('/administrator/') !== -1;
    }

    function isActiveField(elm) {
        return elm.querySelector('.wf-media-input-active') !== null;
    }

    function cleanInputValue(elm) {
        let val = elm.value || '';

        // clean value first
        if (val.indexOf('#joomlaImage') !== -1) {
            val = val.substring(0, val.indexOf('#'));
            elm.value = val;
            elm.setAttribute('value', val);
        }
    }

    /* global Joomla */


    function getBasePath(elm) {
        // Joomla 3.5.x / 4.x Media Field
        const wrapper = elm.closest('.field-media-wrapper');
        let path = '';

        if (wrapper) {
            // Joomla 3
            if (wrapper.options) {
                path = wrapper.options.basepath || '';
            // Joomla 4+
            } else {
                path = wrapper.basePath || '';
            }
        }

        // get from input for some layout overrides
        path = path || elm.dataset.basepath || '';

        // resolve path for admin
        if (path && !isAdmin(path) && isAdmin(document.location.href)) {
            path += 'administrator/';
        }

        return path;
    }

    function updateMediaUrl(row, options) {
        const elements = Array.from(row.querySelectorAll('.field-media-wrapper'));

        if (!elements.length) {
            elements.push(row);
        }

        elements.forEach(function (el) {
            const inp = el.querySelector('.field-media-input');

            if (!inp) {
                return;
            }

            if (inp.disabled) {
                return;
            }

            let id = inp.getAttribute('id');

            if (!id) {
                return;
            }

            // update field id with index
            if (id.indexOf('rowX') !== -1) {
                const rowIndex = row.parentNode ? Array.from(row.parentNode.children).indexOf(row) : 0;
                id = id.replace('rowX', 'row' + rowIndex);
                inp.setAttribute('id', id);
            }

            el.classList.add('wf-media-wrapper');

            // get url from data attribute or custom element attribute
            let dataUrl = el.dataset.url || el.getAttribute('url') || '';

            // legacy modal link btn
            const linkBtn = el.querySelector('a[href*="index.php?option=com_media"].modal.btn');

            if (linkBtn && !dataUrl) {
                dataUrl = linkBtn.getAttribute('href') || '';
            }

            // parse url parameters
            const params = parseUrl(dataUrl);

            // set mediatype default to "images"
            let mediatype = 'images';

            // set plugin (may contain caller), defaults to browser
            const plugin = params.plugin ? params.plugin : 'browser';

            // process a parameter
            if (params.mediatype) {
                mediatype = params.mediatype;
            // or layout override of url set to files
            } else if (params.view === 'files') {
                mediatype = 'files';
            }

            // get supported extensions from converted mediafield
            if (inp.classList.contains('wf-media-input-converted')) {
                let supportedExtensions = false;

                try {
                    supportedExtensions = JSON.parse(el.getAttribute('supported-extensions') || '{}');
                } catch (e) {
                    supportedExtensions = false;
                }

                if (supportedExtensions) {
                    const extensions = [];

                    Object.entries(supportedExtensions).forEach(function ([, values]) {
                        if (Array.isArray(values) && values.length) {
                            extensions.push(...values);
                        }
                    });

                    if (extensions.length) {
                        mediatype = extensions.join(',');
                    }
                }
            }

            // create url
            let url = getBasePath(inp) + 'index.php?option=com_jce&task=plugin.display&plugin=' + plugin + '&fieldid=' + id + '&mediatype=' + mediatype;

            if (options.context) {
                params.context = options.context;
            }

            const invalidParams = ['option', 'task', 'plugin', 'fieldid', 'mediatype', 'element', 'view', 'tmpl'];

            invalidParams.forEach(function (key) {
                delete params[key];
            });

            const paramStr = new URLSearchParams(params).toString();

            if (paramStr) {
                url += '&' + paramStr;
            }

            // update data url attribute
            if (el.dataset.url) {
                el.dataset.url = url;
            }

            // update custom element
            if (el.matches('joomla-field-media, .wf-media-wrapper-custom')) {
                el.setAttribute('url', url);

                // create new iframe
                const ifrHtml = Joomla.sanitizeHtml('<iframe src="' + url + '" class="iframe" title="" width="100%" height="100%"></iframe>', { iframe: ['src', 'class', 'title', 'width', 'height'] });

                // update attributes
                const modal = el.querySelector('.joomla-modal');

                if (modal) {
                    modal.setAttribute('data-url', url);
                    modal.setAttribute('data-iframe', ifrHtml);
                }

                // remove width and height attributes (Helix Ultimate layout override)
                el.removeAttribute('modal-width');
                el.removeAttribute('modal-height');
            }

            // update link button
            if (linkBtn) {
                linkBtn.setAttribute('href', url);
            }
        });
    }

    function createPreview(field, url, mimeType) {
        if (!field || !field.previewElement) {
            return;
        }

        // remove existing preview
        field.previewElement.innerHTML = '';

        // get the type of the file, checking "text" types again against the file extension
        if (!mimeType || mimeType.indexOf('text/') === 0) {
            mimeType = mimeFromExt(url);
        }

        // create new element
        let el;

        if (mimeType && mimeType.indexOf('image/') === 0) {
            el = document.createElement('img');
            el.src = url;
            el.alt = 'Preview';
        } else if (mimeType && mimeType.indexOf('video/') === 0) {
            el = document.createElement('video');
            el.preload = 'metadata';
            el.controls = true;
            el.src = url;
            el.type = mimeType;
        } else if (mimeType && mimeType.indexOf('audio/') === 0) {
            el = document.createElement('audio');
            el.preload = 'none';
            el.controls = true;
            el.src = url;
            el.type = mimeType;
        } else {
            el = document.createElement('object');
            el.data = url;
            el.type = mimeType || 'application/octet-stream';
        }

        field.previewElement.appendChild(el);
    }

    function disableCustomElementButtons(elm) {
        if (elm.button && elm.button.hasAttribute('disabled')) {
            elm.button.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopImmediatePropagation();
            }, true);
        }

        if (elm.buttonClearEl && elm.buttonClearEl.hasAttribute('disabled')) {
            elm.buttonClearEl.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopImmediatePropagation();
            }, true);
        }
    }

    function initMediaField(field) {
        field.addEventListener('joomla-field-media:update', function () {
            if (!field.inputElement) {
                return;
            }

            // clean value before processing
            cleanInputValue(field.inputElement);

            // copy markValid function or noop
            const markValidFunction = field.markValid || function () {};

            // override markValid and treat as a callback to clean the input value
            field.markValid = function () {
                cleanInputValue(this.inputElement);

                // markValid (check for label)
                if (field.querySelector('label[for="' + this.inputElement.id + '"]')) {
                    markValidFunction.apply(this);
                }
            };

            let url = field.basePath + field.inputElement.value;

            // prevent validation and update of field value
            field.inputElement.addEventListener('change', function (e) {
                // ignore programmatically dispatched events to avoid recursion
                if (!e.isTrusted) {
                    return;
                }

                e.stopImmediatePropagation();

                cleanInputValue(this);

                // markValid (check for label)
                if (field.querySelector('label[for="' + this.id + '"]')) {
                    markValidFunction.apply(this);
                }

                // update the url with the updated value
                url = field.basePath + this.value;

                fetch(url, { method: 'HEAD' })
                    .then(function (res) {
                        if (!res.ok) {
                            return;
                        }

                        // Content-Type is CORS-safelisted, usually accessible without expose-headers
                        const contentType = (res.headers.get('Content-Type') || '').split(';')[0].trim();

                        if (contentType) {
                            field.mimeType = contentType;
                        } else {
                            field.mimeType = mimeFromExt(url);
                        }
                    })
                    // eslint-disable-next-line dot-notation
                    .catch(function () {
                        field.mimeType = mimeFromExt(url);
                    })
                    // eslint-disable-next-line dot-notation
                    .finally(function () {
                        createPreview(field, url, field.mimeType);
                    });

                // trigger update for t4 builder
                document.dispatchEvent(new CustomEvent('t4:media-selected', { detail: { selectedUrl: field.basePath + this.value } }));

                // external change event
                this.dispatchEvent(new Event('change'));
            }, true);

            if (field.inputElement.value) {
                // build the previewElement
                createPreview(field, url, field.mimeType);
            }
        });
    }

    function initRepeatable(options) {
        document.addEventListener('subform-row-add', function (evt) {
            const row = evt.detail && evt.detail.row;

            if (!row) {
                return;
            }

            if (!row.querySelector('.wf-media-input')) {
                return;
            }

            if (isActiveField(row)) {
                row.querySelectorAll('.wf-media-input').forEach(function (inp) {
                    const mediaField = inp.closest('joomla-field-media');

                    if (mediaField) {
                        mediaField.classList.add('wf-media-wrapper');
                    }

                    if (inp.classList.contains('wf-media-input-active')) {
                        inp.removeAttribute('readonly');
                    }
                });

                // update joomla-field-media elements
                row.querySelectorAll('joomla-field-media.wf-media-wrapper').forEach(function (el) {
                    el.dispatchEvent(new CustomEvent('joomla-field-media:update'));
                });

                updateMediaUrl(row, options);
            } else {
                row.querySelectorAll('.wf-media-input').forEach(function (inp) {
                    inp.disabled = true;

                    const mediaField = inp.closest('joomla-field-media');

                    if (mediaField) {
                        mediaField.classList.add('wf-media-wrapper');
                    }
                });

                row.querySelectorAll('joomla-field-media').forEach(function (el) {
                    el.querySelectorAll('button').forEach(function (btn) {
                        btn.style.display = 'none';
                        btn.disabled = true;
                    });

                    disableCustomElementButtons(el);
                });

                const subform = row.closest('joomla-field-subform');

                if (subform) {
                    subform.querySelectorAll('button').forEach(function (btn) {
                        btn.style.display = 'none';
                        btn.disabled = true;
                        btn.addEventListener('click', function (e) {
                            e.preventDefault();
                            e.stopImmediatePropagation();
                        });
                    });
                }
            }
        });
    }

    /* global Joomla */


    document.addEventListener('DOMContentLoaded', function () {
        const options = Joomla.getOptions('plg_system_jce', {});

        // process media input wrapper
        document.querySelectorAll('.wf-media-input').forEach(function (inp) {
            const wrapper = inp.closest('.field-media-wrapper, .fc-field-value-properties-box');

            if (wrapper) {
                wrapper.classList.add('wf-media-wrapper');
            }
        });

        // remove readonly attribute on active media inputs
        document.querySelectorAll('.wf-media-input-active').forEach(function (el) {
            el.removeAttribute('readonly');
        });

        // remove modal heading
        document.querySelectorAll('.wf-media-wrapper .modal-header h3').forEach(function (el) {
            el.innerHTML = '&nbsp;';
        });

        document.querySelectorAll('.wf-media-wrapper button.button-select').forEach(function (btn) {
            btn.addEventListener('click', function (e) {
                e.preventDefault();
            });
        });

        // disable media input and prevent button click
        document.querySelectorAll('.wf-media-input').forEach(function (inp) {
            if (inp.classList.contains('wf-media-input-active')) {
                return;
            }

            inp.disabled = true;

            const parent = inp.parentElement;

            if (parent) {
                parent.querySelectorAll('button, a.btn').forEach(function (btn) {
                    btn.disabled = true;
                    btn.removeAttribute('onclick');
                    btn.style.display = 'none';
                    btn.addEventListener('click', function (e) {
                        e.preventDefault();
                        e.stopImmediatePropagation();
                    });
                });
            }
        });

        // update existing repeatable
        document.querySelectorAll('.wf-media-input').forEach(function (inp) {
            const row = inp.closest('.subform-repeatable-group');

            if (!row) {
                return;
            }

            if (!isActiveField(row)) {
                const subform = row.closest('joomla-field-subform');

                if (subform) {
                    subform.querySelectorAll('button').forEach(function (btn) {
                        btn.style.display = 'none';
                        btn.disabled = true;
                        btn.addEventListener('click', function (e) {
                            e.preventDefault();
                            e.stopImmediatePropagation();
                        });
                    });
                }
            }
        });

        // repeatable when created
        initRepeatable(options);

        // disable button actions (Joomla 4 and Joomla 5)
        document.querySelectorAll('joomla-field-media.wf-media-wrapper').forEach(function (el) {
            disableCustomElementButtons(el);
        });

        // joomla custom attribute and media field override
        document.querySelectorAll('joomla-field-media.wf-media-wrapper').forEach(function (field) {
            initMediaField(field);
            field.dispatchEvent(new CustomEvent('joomla-field-media:update'));
            updateMediaUrl(field, options);
        });

        // nasty fix for Joomla 5.1 media dialog
        document.addEventListener('joomla-dialog:open', function (e) {
            const target = e.target;

            if (target.classList.contains('joomla-dialog-media-field')) {
                const ifr = target.querySelector('iframe');

                if (ifr && ifr.src.indexOf('index.php?option=com_jce') !== -1) {
                    target.classList.add('wf-media-dialog');
                }
            }
        });
    });

})();
